import React from 'react';

function Contact() {
  return (
    <section className="contact" style={{ padding: '50px', textAlign: 'center' }}>
      <h2>Contact Us</h2>
      <p>Email: contact@justcarpent.com</p>
      <p>Phone: +123 456 7890</p>
      <p>Address: 123 Woodwork Lane, Carpenter City</p>
    </section>
  );
}

export default Contact;
